double dummy_y0[6];

double matrix[6][6];

void read() {
    double cy[36];

    double res;
    res = sharing_array(dummy_y0, 6, cy, 36);

    for (row:int[0,5]) {
        for (column:int[0,5]) {
            matrix[row][column] = cy[row*6+column];
        }
    }
}

